package lk.gov.health.govcare.system;
import lk.gov.health.govcare.common.*;import lk.gov.health.govcare.security.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/search") public class SearchController{private final SqlSupport sql;private final CurrentUser current;public SearchController(SqlSupport sql,CurrentUser current){this.sql=sql;this.current=current;}
@GetMapping("/suggestions")public List<Map<String,Object>> search(@RequestParam String q,@RequestParam(defaultValue="8")int limit,@RequestParam(defaultValue="all")String scope){GovCarePrincipal a=current.get();String term=q==null?"":q.trim();if(term.length()<2)throw ApiException.badRequest("Search query requires at least two characters.");int n=Math.max(1,Math.min(limit,30));String like="%"+term+"%";List<Map<String,Object>> out=new ArrayList<>();if(!Set.of("users").contains(scope)&&!Set.of("patient","guardian").contains(a.role()))out.addAll(sql.list("select id::text id,patient_no||' - '||full_name label,concat_ws(' | ','Patient',gender::text,phone,nic) description,'Patient' category,'/patients/'||id::text href from patients where hospital_id=:hospital and status<>'deleted' and(full_name ilike :q or patient_no ilike :q or coalesce(nic,'') ilike :q or coalesce(phone,'') ilike :q or coalesce(email,'') ilike :q) order by updated_at desc limit :limit",map("hospital",a.hospitalId(),"q",like,"limit",Math.min(n,8))));if(Set.of("all","users").contains(scope)){out.addAll(sql.list("select u.id::text id,u.full_name label,concat_ws(' | ',initcap(replace(u.role::text,'_',' ')),u.email,d.name,u.status::text) description,'Staff' category,case when :portal then '/portal/appointments' else '/admin/staff?selected='||u.id::text end href from app_users u left join departments d on d.id=u.department_id where u.hospital_id=:hospital and u.status<>'deleted' and(:portal=false or u.role::text in('doctor','surgeon','radiologist','pathologist')) and(u.full_name ilike :q or u.email ilike :q or coalesce(u.phone,'') ilike :q or u.role::text ilike :q or coalesce(d.name,'') ilike :q) order by u.updated_at desc limit :limit",map("hospital",a.hospitalId(),"q",like,"limit",Math.min(n,8),"portal",Set.of("patient","guardian").contains(a.role()))));}return out.stream().limit(n).toList();}private static Map<String,Object>map(Object...x){Map<String,Object>m=new HashMap<>();for(int i=0;i<x.length;i+=2)m.put(String.valueOf(x[i]),x[i+1]);return m;}}
